    public virtual void handleOHLCV(WebSocketClient client, object message)
    {
        //
        //     {
        //         "action": "snapshot",
        //         "arg": {
        //             "instType": "SPOT",
        //             "channel": "candle1m",
        //             "instId": "BTCUSDT"
        //         },
        //         "data": [
        //             [
        //                 "1701871620000",
        //                 "44080.23",
        //                 "44080.23",
        //                 "44028.5",
        //                 "44028.51",
        //                 "9.9287",
        //                 "437404.105512",
        //                 "437404.105512"
        //             ],
        //             [
        //                 "1701871680000",
        //                 "44028.51",
        //                 "44108.11",
        //                 "44028.5",
        //                 "44108.11",
        //                 "17.139",
        //                 "755436.870643",
        //                 "755436.870643"
        //             ],
        //         ],
        //         "ts": 1701901610417
        //     }
        //
        // uta
        //
        //     {
        //         "action": "snapshot",
        //         "arg": {
        //             "instType": "usdt-futures",
        //             "topic": "kline",
        //             "symbol": "BTCUSDT",
        //             "interval": "1m"
        //         },
        //         "data": [
        //             {
        //                 "start": "1755564480000",
        //                 "open": "116286",
        //                 "close": "116256.2",
        //                 "high": "116310.2",
        //                 "low": "116232.8",
        //                 "volume": "39.7062",
        //                 "turnover": "4616746.46654"
        //             },
        //         ],
        //         "ts": 1755594421877
        //     }
        //
        IDictionary<string, object> arg = this.safeDict(message, "arg", new Dictionary<string, object>() {});
        string? instType = this.safeStringLower(arg, "instType");
        string marketType = "contract";
        if (instType == "spot")
        {
            marketType = "spot";
        }
        string? marketId = this.safeString2(arg, "instId", "symbol");
        Dictionary<string, object> market = this.safeMarket(marketId, null, null, marketType);
        string? symbol = ((string)(market.ContainsKey("symbol") ? market["symbol"] : null));
        ((IDictionary<string,object>)this.ohlcvs)[(string)symbol] = this.safeDict(this.ohlcvs, symbol, new Dictionary<string, object>() {});
        string? channel = this.safeString2(arg, "channel", "topic", "");
        string? interval = this.safeString(arg, "interval");
        bool? isUta = null;
        if ((interval == null))
        {
            isUta = false;
            interval = channel.Replace("candle", (string)"");
        } else
        {
            isUta = true;
        }
        IDictionary<string, object> timeframes = this.safeDict(this.options, "timeframes");
        string? timeframe = this.findTimeframe(interval, timeframes);
        if ((timeframe == null))
        {
            return;
        }
        ccxt.pro.ArrayCacheByTimestamp stored = ((ccxt.pro.ArrayCacheByTimestamp)this.safeValue(this.safeValue(this.ohlcvs, symbol), timeframe));
        if ((stored == null))
        {
            Int64? limit = this.safeInteger(this.options, "OHLCVLimit", 1000);
            stored = new ArrayCacheByTimestamp(limit);
            ((IDictionary<string,object>)getValue(this.ohlcvs, symbol))[timeframe] = stored;
        }
        List<object> data = this.safeList(message, "data", new List<object>() {});
        for (int i = 0; i < data.Count; i++)
        {
            List<object> parsed = this.parseWsOHLCV(data[i], market);
            stored.append(parsed);
        }
        string? messageHash = null;
        if ((isUta == true))
        {
            messageHash = ("kline:" + symbol);
        } else
        {
            messageHash = ((("candles:" + timeframe) + ":") + symbol);
        }
        client.resolve(stored, messageHash);
    }

    public override List<object> parseWsOHLCV(object ohlcv, object market = null)
    {
        //
        //     [
        //         "1701871620000",  // timestamp
        //         "44080.23", // open
        //         "44080.23", // high
        //         "44028.5", // low
        //         "44028.51", // close
        //         "9.9287", // base volume
        //         "437404.105512", // quote volume
        //         "437404.105512" // USDT volume
        //     ]
        //
        // uta
        //
        //     {
        //         "start": "1755564480000",
        //         "open": "116286",
        //         "close": "116256.2",
        //         "high": "116310.2",
        //         "low": "116232.8",
        //         "volume": "39.7062",
        //         "turnover": "4616746.46654"
        //     }
        //
        int volumeIndex = 5;
        if (((market != null)) && (isEqual(getValue(market, "inverse"), true)))
        {
            volumeIndex = 6;
        }
        return new List<object> {this.safeInteger2(ohlcv, "start", 0), this.safeNumber2(ohlcv, "open", 1), this.safeNumber2(ohlcv, "high", 2), this.safeNumber2(ohlcv, "low", 3), this.safeNumber2(ohlcv, "close", 4), this.safeNumber2(ohlcv, "volume", volumeIndex)};
    }

