     */
    public async override Task<List<ccxt.Trade>> WatchTrades(string symbol, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        return await this.WatchTradesForSymbols(new List<object>() {symbol},ccxt.BaseExchange.ToInt64Arg(since),ccxt.BaseExchange.ToInt64Arg(limit), parameters);
    }

    /**
     * @method
     * @name bitget#watchTradesForSymbols
     * @description get the list of most recent trades for a particular symbol
     * @see https://www.bitget.com/api-doc/spot/websocket/public/Trades-Channel
     * @see https://www.bitget.com/api-doc/contract/websocket/public/New-Trades-Channel
     * @see https://www.bitget.com/api-doc/uta/websocket/public/New-Trades-Channel
     * @param {string[]} symbols unified symbol of the market to fetch trades for
     * @param {int} [since] timestamp in ms of the earliest trade to fetch
     * @param {int} [limit] the maximum amount of trades to fetch
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {boolean} [params.uta] set to true for the unified trading account (uta), defaults to false
     * @returns {object[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=public-trades}
     */
    public async override Task<List<ccxt.Trade>> WatchTradesForSymbols(object symbols, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        Int64? limitVar = limit;
        parameters ??= new Dictionary<string, object>();
        int symbolsLength = getArrayLength(symbols);
        if ((symbolsLength == 0))
        {
            throw new ArgumentsRequired ((this.id + " watchTradesForSymbols() requires a non-empty array of symbols")) ;
        }
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        symbols = this.marketSymbols(symbols);
        bool? uta = null;
        IList<object> utaparametersVariable = (IList<object>)this.handleOptionBoolAndParams(parameters, "watchTradesForSymbols", "uta", false);
        uta = (bool?)utaparametersVariable[0];
        parameters = utaparametersVariable[1];
        List<object> topics = new List<object>() {};
        List<object> messageHashes = new List<object>() {};
        for (int i = 0; i < getArrayLength(symbols); i++)
        {
            string? symbol = ((string)getValue(symbols, i));
            Dictionary<string, object> market = this.market(symbol);
            string? instType = null;
            var instTypeparametersVariable = this.getInstType("watchTradesForSymbols", market, uta, parameters);
            instType = (string)instTypeparametersVariable[0];
            parameters = instTypeparametersVariable[1];
            Dictionary<string, object> args = new Dictionary<string, object>() {
                { "instType", instType },
            };
            string topicOrChannel = "channel";
            if ((uta == true))
            {
                topicOrChannel = "topic";
            }
            string symbolOrInstId = "instId";
            if ((uta == true))
            {
                symbolOrInstId = "symbol";
            }
            args[(string)topicOrChannel] = uta == true ? "publicTrade" : "trade";
            args[(string)symbolOrInstId] = (market.ContainsKey("id") ? market["id"] : null);
            topics.Add(args);
            messageHashes.Add(("trade:" + symbol));
        }
        if ((uta == true))
        {
            parameters = this.extend(parameters, new Dictionary<string, object>() {
                { "uta", true },
            });
        }
        object trades = await this.watchPublicMultiple(uta, messageHashes, topics, parameters);
        if (this.newUpdates)
        {
            IDictionary<string, object> first = this.safeDict(trades, 0);
            string? tradeSymbol = this.safeString(first, "symbol");
            limitVar = ((Int64?)callDynamically(trades, "getLimit", new object[] {tradeSymbol, limitVar}));
        }
        IList<object> result = this.filterBySinceLimit(trades, since, limitVar, "timestamp", true);
        if (isEqual(this.handleOption("watchTrades", "ignoreDuplicates", true), true))
        {
            object filtered = this.removeRepeatedTradesFromArray(result);
            filtered = this.sortBy(filtered, "timestamp");
            return ccxt.BaseExchange.ToTradeList(filtered);
        }
        return ccxt.BaseExchange.ToTradeList(result);
    }

    /**
     * @method
     * @name bitget#unWatchTrades
     * @description unsubscribe from the trades channel
     * @see https://www.bitget.com/api-doc/spot/websocket/public/Trades-Channel
     * @see https://www.bitget.com/api-doc/contract/websocket/public/New-Trades-Channel
     * @see https://www.bitget.com/api-doc/uta/websocket/public/New-Trades-Channel
     * @param {string} symbol unified symbol of the market to unwatch the trades for
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {boolean} [params.uta] set to true for the unified trading account (uta), defaults to false
     * @returns {any} status of the unwatch request
     */
    public async override Task<object> unWatchTrades(string? symbol, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        List<object> values = this.handleOptionBoolAndParams(parameters, "watchTrades", "uta", false);
        object uta = (values != null && 0 < values.Count ? values[0] : null);
        string channelTopic = "trade";
        if (isTrue(uta))
        {
            channelTopic = "publicTrade";
        }
        return await this.unWatchChannel(symbol, channelTopic, "trade", "watchTrades", parameters);
    }

    public virtual void handleTrades(WebSocketClient client, Dictionary<string, object> message)
    {
        //
        //     {
        //         "action": "snapshot",
        //         "arg": { "instType": "SPOT", "channel": "trade", "instId": "BTCUSDT" },
        //         "data": [
        //             {
        //                 "ts": "1701910980366",
        //                 "price": "43854.01",
        //                 "size": "0.0535",
        //                 "side": "buy",
        //                 "tradeId": "1116461060594286593"
        //             },
        //         ],
        //         "ts": 1701910980730
        //     }
        //
        // uta
        //
        //     {
        //         "action": "snapshot",
        //         "arg": { "instType": "spot", "topic": "publicTrade", "symbol": "BTCUSDT" },
        //         "data": [
        //             {
        //                 "T": "1756287827920",
        //                 "P": "110878.5",
        //                 "v": "0.07",
        //                 "S": "buy",
        //                 "L": "1344534089797185550"
        //                 "i": "1344534089797185549"
        //             },
        //         ],
        //         "ts": 1701910980730
        //     }
        //
        IDictionary<string, object> arg = this.safeDict(message, "arg", new Dictionary<string, object>() {});
        string? instType = this.safeStringLower(arg, "instType");
        string marketType = "contract";
        if (instType == "spot")
        {
            marketType = "spot";
        }
        string? marketId = this.safeString2(arg, "instId", "symbol");
        Dictionary<string, object> market = this.safeMarket(marketId, null, null, marketType);
        string? symbol = ((string)(market.ContainsKey("symbol") ? market["symbol"] : null));
        ccxt.pro.ArrayCache stored = ((ccxt.pro.ArrayCache)this.safeValue(this.trades, symbol));
        if ((stored == null))
        {
            Int64? limit = this.safeInteger(this.options, "tradesLimit", 1000);
            stored = new ArrayCache(limit);
            ((IDictionary<string,object>)this.trades)[(string)symbol] = stored;
        }
        List<object> data = this.safeList(message, "data", new List<object>() {});
        int length = data.Count;
        // fix chronological order by reversing
        for (object i = 0; isLessThan(i, length); postFixIncrement(ref i))
        {
            object index = subtract(subtract(length, i), 1);
            object rawTrade = getValue(data, index);
            Dictionary<string, object> parsed = this.parseWsTrade(rawTrade, market);
            stored.append(parsed);
        }
        string messageHash = ("trade:" + symbol);
        client.resolve(stored, messageHash);
    }

    public override Dictionary<string, object> parseWsTrade(object trade, object market = null)
    {
        //
        //     {
        //         "ts": "1701910980366",
        //         "price": "43854.01",
        //         "size": "0.0535",
        //         "side": "buy",
        //         "tradeId": "1116461060594286593"
        //     }
        // swap private
        //
        //            {
        //               "orderId": "1169142761031114781",
        //               "tradeId": "1169142761312637004",
        //               "symbol": "LTCUSDT",
        //               "orderType": "market",
        //               "side": "buy",
        //               "price": "80.87",
        //               "baseVolume": "0.1",
        //               "quoteVolume": "8.087",
        //               "profit": "0",
        //               "tradeSide": "open",
        //               "posMode": "hedge_mode",
        //               "tradeScope": "taker",
        //               "feeDetail": [
        //                  {
        //                     "feeCoin": "USDT",
        //                     "deduction": "no",
        //                     "totalDeductionFee": "0",
        //                     "totalFee": "-0.0048522"
        //                  }
        //               ],
        //               "cTime": "1714471276596",
        //               "uTime": "1714471276596"
        //            }
        // spot private
        //        {
        //           "orderId": "1169142457356959747",
        //           "tradeId": "1169142457636958209",
        //           "symbol": "LTCUSDT",
        //           "orderType": "market",
        //           "side": "buy",
        //           "priceAvg": "81.069",
        //           "size": "0.074",
        //           "amount": "5.999106",
        //           "tradeScope": "taker",
        //           "feeDetail": [
        //              {
        //                 "feeCoin": "LTC",
        //                 "deduction": "no",
        //                 "totalDeductionFee": "0",
        //                 "totalFee": "0.000074"
        //              }
        //           ],
        //           "cTime": "1714471204194",
        //           "uTime": "1714471204194"
        //        }
        //
        // uta private
        //
        //     {
        //         "symbol": "BTCUSDT",
        //         "orderType": "market",
        //         "updatedTime": "1736378720623",
        //         "side": "buy",
        //         "orderId": "1288888888888888888",
        //         "execPnl": "0",
        //         "feeDetail": [
        //             {
        //                 "feeCoin": "USDT",
        //                 "fee": "0.569958"
        //             }
        //         ],
        //         "execTime": "1736378720623",
        //         "tradeScope": "taker",
        //         "tradeSide": "open",
        //         "execId": "1288888888888888888",
        //         "execLinkId": "1288888888888888888",
        //         "execPrice": "94993",
        //         "holdSide": "long",
        //         "execValue": "949.93",
        //         "category": "USDT-FUTURES",
        //         "execQty": "0.01",
        //         "clientOid": "1288888888888888889"
        // uta
        //
        //     {
        //         "i": "1344534089797185549", // Fill execution ID
        //         "L": "1344534089797185550", // Execution correlation ID
        //         "p": "110878.5", // Fill price
        //         "v": "0.07", // Fill size
        //         "S": "buy", // Fill side
        //         "T": "1756287827920" // Fill timestamp
        //     }
        //
        string? instId = this.safeString2(trade, "symbol", "instId");
        string? posMode = this.safeString(trade, "posMode");
        string? category = this.safeString(trade, "category");
        string? defaultType = null;
        if ((category != null))
        {
            defaultType = (category != "SPOT") ? "contract" : "spot";
        } else
        {
            defaultType = ((posMode != null)) ? "contract" : "spot";
        }
        if ((market == null))
        {
            market = this.safeMarket(instId, null, null, defaultType);
        }
        Int64? timestamp = this.safeIntegerN(trade, new List<object>() {"uTime", "cTime", "ts", "T", "execTime"});
        List<object> feeDetail = this.safeList(trade, "feeDetail", new List<object>() {});
        IDictionary<string, object> first = this.safeDict(feeDetail, 0);
        Dictionary<string, object> fee = null;
        if ((first != null))
        {
            string? feeCurrencyId = this.safeString(first, "feeCoin");
            string? feeCurrencyCode = this.safeCurrencyCode(feeCurrencyId);
            fee = new Dictionary<string, object>() {
                { "cost", Precise.stringAbs(this.safeString2(first, "totalFee", "fee")) },
                { "currency", feeCurrencyCode },
            };
        }
        return this.safeTrade(new Dictionary<string, object>() {
            { "info", trade },
            { "id", this.safeStringN(trade, new List<object>() {"tradeId", "i", "execId"}) },
            { "order", this.safeString2(trade, "orderId", "L") },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "symbol", getValue(market, "symbol") },
            { "type", this.safeString(trade, "orderType") },
            { "side", this.safeString2(trade, "side", "S") },
            { "takerOrMaker", this.safeString(trade, "tradeScope") },
            { "price", this.safeStringN(trade, new List<object>() {"priceAvg", "price", "execPrice", "P"}) },
            { "amount", this.safeStringN(trade, new List<object>() {"size", "baseVolume", "execQty", "v"}) },
            { "cost", this.safeStringN(trade, new List<object>() {"amount", "quoteVolume", "execValue"}) },
            { "fee", fee },
        }, market);
    }

    /**
     * @method
     * @name bitget#watchPositions
     * @description watch all open positions
     * @see https://www.bitget.com/api-doc/contract/websocket/private/Positions-Channel
     * @see https://www.bitget.com/api-doc/uta/websocket/private/Positions-Channel
     * @param {string[]|undefined} symbols list of unified market symbols
     * @param {int} [since] the earliest time in ms to fetch positions for
     * @param {int} [limit] the maximum number of positions to retrieve
     * @param {object} params extra parameters specific to the exchange API endpoint
     * @param {string} [params.instType] one of 'USDT-FUTURES', 'USDC-FUTURES', 'COIN-FUTURES', 'SUSDT-FUTURES', 'SUSDC-FUTURES' or 'SCOIN-FUTURES', default is 'USDT-FUTURES'
     * @param {boolean} [params.uta] set to true for the unified trading account (uta), defaults to false
     * @returns {object[]} a list of [position structure]{@link https://docs.ccxt.com/en/latest/manual.html#position-structure}
     */
    public async override Task<List<ccxt.Position>> WatchPositions(object symbols = null, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        IDictionary<string, object> market = null;
        object messageHash = "";
        string subscriptionHash = "positions";
        object instType = "USDT-FUTURES";
        bool? uta = null;
        IList<object> utaparametersVariable = (IList<object>)this.handleOptionBoolAndParams(parameters, "watchPositions", "uta", false);
        uta = (bool?)utaparametersVariable[0];
        parameters = utaparametersVariable[1];
        symbols = this.marketSymbols(symbols);
        if (((symbols != null)) && !this.isEmpty(symbols))
        {
            market = this.getMarketFromSymbols(symbols);
            var instTypeparametersVariable = this.getInstType("watchPositions", market, uta, parameters);
            instType = instTypeparametersVariable[0];
            parameters = instTypeparametersVariable[1];
        }
        if ((uta == true))
        {
            instType = "UTA";
        }
        messageHash = add(add(instType, ":positions"), messageHash);
        Dictionary<string, object> args = new Dictionary<string, object>() {
            { "instType", instType },
        };
        string topicOrChannel = "channel";
        if ((uta == true))
        {
            topicOrChannel = "topic";
        }
        string channel = "positions";
        if ((uta == true))
        {
            channel = "position";
        }
        args[(string)topicOrChannel] = channel;
        if (uta != true)
        {
            args["instId"] = "default";
        } else
        {
            parameters = this.extend(parameters, new Dictionary<string, object>() {
                { "uta", true },
            });
        }
        object newPositions = await this.watchPrivate(uta, messageHash, subscriptionHash, args, parameters);
        if (this.newUpdates)
        {
            return ccxt.BaseExchange.ToPositionList(newPositions);
        }
        return ccxt.BaseExchange.ToPositionList(this.filterBySymbolsSinceLimit(newPositions, symbols, since, limit, true));
    }

