            { "liquidationPrice", this.safeNumber2(position, "liquidationPrice", "liqPrice") },
            { "entryPrice", this.safeNumber2(position, "openPriceAvg", "avgPrice") },
            { "unrealizedPnl", this.safeNumber2(position, "unrealizedPL", "unrealisedPnl") },
            { "percentage", this.parseNumber(percentage) },
            { "contracts", this.safeNumber2(position, "total", "size") },
            { "contractSize", contractSize },
            { "markPrice", this.safeNumber(position, "markPrice") },
            { "side", this.safeString2(position, "holdSide", "posSide") },
            { "hedged", hedged },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "maintenanceMargin", null },
            { "maintenanceMarginPercentage", this.safeNumber2(position, "keepMarginRate", "mmr") },
            { "collateral", this.safeNumber(position, "available") },
            { "initialMargin", this.safeNumber(position, "marginSize") },
            { "initialMarginPercentage", null },
            { "leverage", this.safeNumber(position, "leverage") },
            { "marginRatio", this.safeNumber(position, "marginRate") },
        });
    }

    /**
     * @method
     * @name bitget#watchOrders
     * @description watches information on multiple orders made by the user
     * @see https://www.bitget.com/api-doc/spot/websocket/private/Order-Channel
     * @see https://www.bitget.com/api-doc/spot/websocket/private/Plan-Order-Channel
     * @see https://www.bitget.com/api-doc/contract/websocket/private/Order-Channel
     * @see https://www.bitget.com/api-doc/contract/websocket/private/Plan-Order-Channel
     * @see https://www.bitget.com/api-doc/margin/cross/websocket/private/Cross-Orders
     * @see https://www.bitget.com/api-doc/margin/isolated/websocket/private/Isolate-Orders
     * @see https://www.bitget.com/api-doc/uta/websocket/private/Order-Channel
     * @param {string} symbol unified market symbol of the market orders were made in
     * @param {int} [since] the earliest time in ms to fetch orders for
     * @param {int} [limit] the maximum number of order structures to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {boolean} [params.trigger] *contract only* set to true for watching trigger orders
     * @param {string} [params.marginMode] 'isolated' or 'cross' for watching spot margin orders]
     * @param {string} [params.type] 'spot', 'swap'
     * @param {string} [params.subType] 'linear', 'inverse'
     * @param {boolean} [params.uta] set to true for the unified trading account (uta), defaults to false
     * @returns {object[]} a list of [order structures]{@link https://docs.ccxt.com/?id=order-structure}
     */
    public async override Task<List<ccxt.Order>> WatchOrders(string symbol = null, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        string symbolVar = symbol;
        Int64? limitVar = limit;
        parameters ??= new Dictionary<string, object>();
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        IDictionary<string, object> market = null;
        string? marketId = null;
        bool? isTrigger = null;
        var isTriggerparametersVariable = this.isTriggerOrder(parameters);
        isTrigger = (bool?)((IList<object>)isTriggerparametersVariable)[0];
        parameters = ((IList<object>)isTriggerparametersVariable)[1];
        string messageHash = "order";
        if ((isTrigger == true))
        {
            messageHash = "triggerOrder";
        }
        string subscriptionHash = "order:trades";
        if ((symbolVar != null))
        {
            market = this.market(symbolVar);
            symbolVar = ((string)(market.ContainsKey("symbol") ? market["symbol"] : null));
            marketId = this.safeString(market, "id");
            messageHash = ((messageHash + ":") + (symbolVar));
        }
        bool? uta = null;
        IList<object> utaparametersVariable = (IList<object>)this.handleOptionBoolAndParams(parameters, "watchOrders", "uta", false);
        uta = (bool?)utaparametersVariable[0];
        parameters = utaparametersVariable[1];
        string? productType = this.safeString(parameters, "productType");
        string? type = null;
        IList<object> typeparametersVariable = (IList<object>)this.handleMarketTypeAndParams("watchOrders", market, parameters);
        type = (string)typeparametersVariable[0];
        parameters = typeparametersVariable[1];
        string? subType = null;
        IList<object> subTypeparametersVariable = (IList<object>)this.handleSubTypeAndParams("watchOrders", market, parameters, "linear");
        subType = (string)subTypeparametersVariable[0];
        parameters = subTypeparametersVariable[1];
        if ((type == "spot" || type == "margin") && ((symbolVar == null)))
        {
            marketId = "default";
        }
        if (((productType == null)) && (type != "spot") && ((symbolVar == null)))
        {
            messageHash = ((messageHash + ":") + subType);
        } else if (productType == "USDT-FUTURES")
        {
            messageHash = (messageHash + ":linear");
        } else if (productType == "COIN-FUTURES")
        {
            messageHash = (messageHash + ":inverse");
        } else if (productType == "USDC-FUTURES")
        {
            messageHash = (messageHash + ":usdcfutures"); // non unified channel
        }
        string? instType = null;
        if ((market == null) && type == "spot")
        {
            instType = "SPOT";
        } else
        {
            var instTypeparametersVariable = this.getInstType("watchOrders", market, uta, parameters);
            instType = (string)instTypeparametersVariable[0];
            parameters = instTypeparametersVariable[1];
        }
        if (type == "spot" && ((symbolVar != null)))
        {
            subscriptionHash = ((subscriptionHash + ":") + (symbolVar));
        }
        if ((isTrigger == true))
        {
            subscriptionHash = (subscriptionHash + ":stop"); // we don't want to re-use the same subscription hash for stop orders
        }
        // different from other streams here the 'rest' id is required for spot markets, contract markets require default here
        string? instId = "default";
        if (type == "spot" || type == "margin")
        {
            instId = marketId;
        }
        string channel = "orders";
        if ((isTrigger == true))
        {
            channel = "orders-algo";
        }
        string? marginMode = null;
        IList<object> marginModeparametersVariable = (IList<object>)this.handleMarginModeAndParams("watchOrders", parameters);
        marginMode = (string)marginModeparametersVariable[0];
        parameters = marginModeparametersVariable[1];
        if ((marginMode != null))
        {
            instType = "MARGIN";
            messageHash = ((messageHash + ":") + marginMode);
            if (marginMode == "isolated")
            {
                channel = "orders-isolated";
            } else
            {
                channel = "orders-crossed";
            }
        }
        if ((uta == true))
        {
            instType = "UTA";
            channel = "order";
        }
        subscriptionHash = ((subscriptionHash + ":") + instType);
        Dictionary<string, object> args = new Dictionary<string, object>() {
            { "instType", instType },
        };
        string topicOrChannel = "channel";
        if ((uta == true))
        {
            topicOrChannel = "topic";
        }
        args[(string)topicOrChannel] = channel;
        if (uta != true)
        {
            args["instId"] = instId;
        } else
        {
            parameters = this.extend(parameters, new Dictionary<string, object>() {
                { "uta", true },
            });
        }
        object orders = await this.watchPrivate(uta, messageHash, subscriptionHash, args, parameters);
        if (this.newUpdates)
        {
            limitVar = ((Int64?)callDynamically(orders, "getLimit", new object[] {symbolVar, limitVar}));
        }
        return ccxt.BaseExchange.ToOrderList(this.filterBySymbolSinceLimit(orders, symbolVar, since, limitVar, true));
    }

    public virtual void handleOrder(WebSocketClient client, Dictionary<string, object> message)
    {
        //
        // spot
        //
        //     {
        //         "action": "snapshot",
        //         "arg": { "instType": "SPOT", "channel": "orders", "instId": "BTCUSDT" },
        //         "data": [
        //             // see all examples in parseWsOrder
        //         ],
        //         "ts": 1701923297285
        //     }
        //
        // contract
        //
        //     {
        //         "action": "snapshot",
        //         "arg": { "instType": "USDT-FUTURES", "channel": "orders", "instId": "default" },
        //         "data": [
        //             // see all examples in parseWsOrder
        //         ],
        //         "ts": 1701920595879
        //     }
        //
        // isolated and cross margin
        //
        //     {
        //         "action": "snapshot",
        //         "arg": { "instType": "MARGIN", "channel": "orders-crossed", "instId": "BTCUSDT" },
        //         "data": [
        //             // see examples in parseWsOrder
        //         ],
        //         "ts": 1701923982497
        //     }
        //
        // uta
        //
        //     {
        //         "action": "snapshot",
        //         "arg": {
        //             "instType": "UTA",
        //             "topic": "order"
        //         },
        //         "data": [
        //             {
        //                 "category": "usdt-futures",
        //                 "symbol": "BTCUSDT",
        //                 "orderId": "xxx",
        //                 "clientOid": "xxx",
        //                 "price": "",
        //                 "qty": "0.001",
        //                 "amount": "1000",
        //                 "holdMode": "hedge_mode",
        //                 "holdSide": "long",
        //                 "tradeSide": "open",
        //                 "orderType": "market",
        //                 "timeInForce": "gtc",
        //                 "side": "buy",
        //                 "marginMode": "crossed",
        //                 "marginCoin": "USDT",
        //                 "reduceOnly": "no",
        //                 "cumExecQty": "0.001",
        //                 "cumExecValue": "83.1315",
        //                 "avgPrice": "83131.5",
        //                 "totalProfit": "0",
        //                 "orderStatus": "filled",
        //                 "cancelReason": "",
        //                 "leverage": "20",
        //                 "feeDetail": [
        //                     {
        //                         "feeCoin": "USDT",
        //                         "fee": "0.0332526"
        //                     }
        //                 ],
        //                 "createdTime": "1742367838101",
        //                 "updatedTime": "1742367838115",
        //                 "stpMode": "none"
        //             }
        //         ],
        //         "ts": 1742367838124
        //     }
        //
        IDictionary<string, object> arg = this.safeDict(message, "arg", new Dictionary<string, object>() {});
        string? channel = this.safeString2(arg, "channel", "topic", "");
        string? instType = this.safeStringLower(arg, "instType");
        string? argInstId = this.safeString(arg, "instId");
        string? marketType = null;
        if (instType == "spot")
        {
            marketType = "spot";
        } else if (instType == "margin")
        {
            marketType = "spot";
        } else
        {
            marketType = "contract";
        }
        List<object> data = this.safeList(message, "data", new List<object>() {});
        IDictionary<string, object> first = this.safeDict(data, 0, new Dictionary<string, object>() {});
        string? category = this.safeStringLower(first, "category", instType);
        bool isLinearSwap = (category == "usdt-futures");
        bool isInverseSwap = (category == "coin-futures");
        bool isUSDCFutures = (category == "usdc-futures");
        if (instType == "uta")
        {
            // UTA order/fill pushes carry the real product in 'category' (spot / *-futures);
            // the instType->marketType mapping above defaults UTA to 'contract', which
            // mis-resolves a UTA SPOT order to the swap market and yields a messageHash the
            // watcher never matches. Derive marketType from category for UTA.
            if ((category == "spot") || (category == "margin"))
            {
                marketType = "spot";
            } else
            {
                marketType = "contract";
            }
        }
        if ((this.orders == null))
        {
            Int64? limit = this.safeInteger(this.options, "ordersLimit", 1000);
            this.orders = new ArrayCacheBySymbolById(limit);
            this.triggerOrders = new ArrayCacheBySymbolById(limit);
        }
        bool isTrigger = (channel == "orders-algo") || (channel == "ordersAlgo");
        object stored = isTrigger ? this.triggerOrders : this.orders;
        string messageHash = "order";
        if (isTrigger)
        {
            messageHash = "triggerOrder";
        }
        Dictionary<string, object> marketSymbols = new Dictionary<string, object>() {};
        for (int i = 0; i < data.Count; i++)
        {
            object order = data[i];
            string? marketId = this.safeString2(order, "instId", "symbol", argInstId);
            Dictionary<string, object> market = this.safeMarket(marketId, null, null, marketType);
            Dictionary<string, object> parsed = this.parseWsOrder(order, market);
            callDynamically(stored, "append", new object[] {parsed});
            string? symbol = ((string)(parsed != null && ((IDictionary<string, object>)parsed).ContainsKey("symbol") ? ((IDictionary<string, object>)parsed)["symbol"] : null));
            if ((symbol != null))
            {
                marketSymbols[(string)symbol] = true;
            }
        }
        List<object> keys = new List<object>(((IDictionary<string,object>)marketSymbols).Keys);
        for (int i = 0; i < keys.Count; i++)
        {
            string? symbol = ((string)keys[i]);
            string innerMessageHash = ((messageHash + ":") + symbol);
            if (channel == "orders-crossed")
            {
                innerMessageHash = (innerMessageHash + ":cross");
            } else if (channel == "orders-isolated")
            {
                innerMessageHash = (innerMessageHash + ":isolated");
            }
            client.resolve(stored, innerMessageHash);
        }
        client.resolve(stored, messageHash);
        if (isLinearSwap)
        {
            client.resolve(stored, "order:linear");
        }
        if (isInverseSwap)
        {
            client.resolve(stored, "order:inverse");
        }
        if (isUSDCFutures)
        {
            client.resolve(stored, "order:usdcfutures");
        }
    }

    public override Dictionary<string, object> parseWsOrder(object order, IDictionary<string, object> market = null)
    {
        //
        // spot
        //
        //   {
        //         instId: 'EOSUSDT',
        //         orderId: '1171779081105780739',
        //         price: '0.81075', // limit price, field not present for market orders
        //         clientOid: 'a2330139-1d04-4d78-98be-07de3cfd1055',
        //         notional: '5.675250', // this is not cost! but notional
        //         newSize: '7.0000', // this is not cost! quantity (for limit order or market sell) or cost (for market buy order)
        //         size: '5.6752', // this is not cost, neither quantity, but notional! this field for "spot" can be ignored at all
        //         // Note: for limit order (even filled) we don't have cost value in response, only in market order
        //         orderType: 'limit', // limit, market
        //         force: 'gtc',
        //         side: 'buy',
        //         accBaseVolume: '0.0000', // in case of 'filled', this would be set (for limit orders, this is the only indicator of the amount filled)
        //         priceAvg: '0.00000', // in case of 'filled', this would be set
        //         status: 'live', // live, filled, partially_filled
        //         cTime: '1715099824215',
        //         uTime: '1715099824215',
        //         feeDetail: [],
        //         enterPointSource: 'API'
        //                   #### trigger order has these additional fields: ####
        //         "triggerPrice": "35100",
        //         "price": "35100", // this is same as trigger price
        //         "executePrice": "35123", // this is limit price
        //         "triggerType": "fill_price",
        //         "planType": "amount",
        //                   #### in case order had a partial fill: ####
        //         fillPrice: '35123',
        //         tradeId: '1171775539946528779',
        //         baseVolume: '7', // field present in market order
        //         fillTime: '1715098979937',
        //         fillFee: '-0.0069987',
        //         fillFeeCoin: 'BTC',
        //         tradeScope: 'T',
        //    }
        //
        // contract
        //
        //     {
        //         accBaseVolume: '0', // total amount filled during lifetime for order
        //         cTime: '1715065875539',
        //         clientOid: '1171636690041344003',
        //         enterPointSource: 'API',
        //         feeDetail: [ {
        //             "feeCoin": "USDT",
        //             "fee": "-0.162003"
        //         } ],
        //         force: 'gtc',
        //         instId: 'SEOSSUSDT',
        //         leverage: '10',
        //         marginCoin: 'USDT',
        //         marginMode: 'crossed',
        //         notionalUsd: '10.4468',
        //         orderId: '1171636690028761089',
        //         orderType: 'market',
        //         posMode: 'hedge_mode', // one_way_mode, hedge_mode
        //         posSide: 'short', // short, long, net
        //         price: '0', // zero for market order
        //         reduceOnly: 'no',
        //         side: 'sell',
        //         size: '13', // this is contracts amount
        //         status: 'live', // live, filled, cancelled
        //         tradeSide: 'open',
        //         uTime: '1715065875539'
        //                   #### when filled order is incoming, these additional fields are present too: ###
        //         baseVolume: '9', // amount filled for the incoming update/trade
        //         accBaseVolume: '13', // i.e. 9 has been filled from 13 amount (this value is same as 'size')
        //         fillFee: '-0.0062712',
        //         fillFeeCoin: 'SUSDT',
        //         fillNotionalUsd: '10.452',
        //         fillPrice: '0.804',
        //         fillTime: '1715065875605',
        //         pnl: '0',
        //         priceAvg: '0.804',
        //         tradeId: '1171636690314407937',
        //         tradeScope: 'T',
        //                   #### trigger order has these additional fields:
        //         "triggerPrice": "0.800000000",
        //         "price": "0.800000000",  // <-- this is same as trigger price, actual limit-price is not present in initial response
        //         "triggerType": "mark_price",
        //         "triggerTime": "1715082796679",
        //         "planType": "pl",
        //         "actualSize": "0.000000000",
        //         "stopSurplusTriggerType": "fill_price",
        //         "stopLossTriggerType": "fill_price",
        //     }
        //
        // isolated and cross margin
        //
        //     {
        //         enterPointSource: "web",
        //         feeDetail: [
        //           {
        //             feeCoin: "AAVE",
        //             deduction: "no",
        //             totalDeductionFee: "0",
        //             totalFee: "-0.00010740",
        //           },
        //         ],
        //         force: "gtc",
        //         orderType: "limit",
        //         price: "93.170000000",
        //         fillPrice: "93.170000000",
        //         baseSize: "0.110600000", // total amount of order
        //         quoteSize: "10.304602000", // total cost of order (independently if order is filled or pending)
        //         baseVolume: "0.107400000", // filled amount of order (during order's lifecycle, and not for this specific incoming update)
        //         fillTotalAmount: "10.006458000", // filled cost of order (during order's lifecycle, and not for this specific incoming update)
        //         side: "buy",
        //         status: "partially_filled",
        //         cTime: "1717875017306",
        //         clientOid: "b57afe789a06454e9c560a2aab7f7201",
        //         loanType: "auto-loan",
        //         orderId: "1183419084588060673",
        //       }
        //
        // uta
        //
        //     {
        //         "category": "usdt-futures",
        //         "symbol": "BTCUSDT",
        //         "orderId": "xxx",
        //         "clientOid": "xxx",
        //         "price": "",
        //         "qty": "0.001",
        //         "amount": "1000",
        //         "holdMode": "hedge_mode",
        //         "holdSide": "long",
        //         "tradeSide": "open",
        //         "orderType": "market",
        //         "timeInForce": "gtc",
        //         "side": "buy",
        //         "marginMode": "crossed",
        //         "marginCoin": "USDT",
        //         "reduceOnly": "no",
        //         "cumExecQty": "0.001",
        //         "cumExecValue": "83.1315",
        //         "avgPrice": "83131.5",
        //         "totalProfit": "0",
        //         "orderStatus": "filled",
        //         "cancelReason": "",
        //         "leverage": "20",
        //         "feeDetail": [
        //             {
        //                 "feeCoin": "USDT",
        //                 "fee": "0.0332526"
        //             }
        //         ],
        //         "createdTime": "1742367838101",
        //         "updatedTime": "1742367838115",
        //         "stpMode": "none"
        //     }
        //
        bool isSpot = !((order != null && ((IDictionary<string, object>)order).ContainsKey("posMode")));
        bool isMargin = ((order != null && ((IDictionary<string, object>)order).ContainsKey("loanType")));
        string? category = this.safeStringLower(order, "category");
        if (category == "spot")
        {
            isSpot = true;
        }
        if (category == "margin")
        {
            isMargin = true;
        }
        string? marketId = this.safeString2(order, "instId", "symbol");
        market = this.safeMarket(marketId, market);
        Int64? timestamp = this.safeInteger2(order, "cTime", "createdTime");
        string? symbol = ((string)(market != null && market.ContainsKey("symbol") ? market["symbol"] : null));
        string? rawStatus = this.safeString2(order, "status", "orderStatus");
        List<object> orderFee = this.safeList(order, "feeDetail", new List<object>() {});
        IDictionary<string, object> fee = this.safeDict(orderFee, 0);
        string? feeAmount = this.safeString(fee, "fee");
        Dictionary<string, object> feeObject = null;
        if ((feeAmount != null))
        {
            string? feeCurrency = this.safeString(fee, "feeCoin");
            feeObject = new Dictionary<string, object>() {
                { "cost", this.parseNumber(Precise.stringAbs(feeAmount)) },
                { "currency", this.safeCurrencyCode(feeCurrency) },
            };
        }
        double? triggerPrice = this.safeNumber(order, "triggerPrice");
        bool isTriggerOrder = ((triggerPrice != null));
        double? price = null;
        if (!isTriggerOrder)
        {
            price = this.safeNumber(order, "price");
        } else if (isSpot && isTriggerOrder)
        {
            // for spot trigger order, limit price is this
            price = this.safeNumber(order, "executePrice");
        }
        string? avgPriceString = this.safeStringLowerN(order, new List<object>() {"priceAvg", "fillPrice", "avgPrice"});
        string? avgPrice = ((avgPriceString == null)) ? null : this.omitZero(avgPriceString);
        string? side = this.safeString(order, "side");
        string? type = this.safeString(order, "orderType");
        string? accBaseVolume = ((string)this.omitZero(this.safeString2(order, "accBaseVolume", "cumExecQty")));
        string? newSizeValue = ((string)this.omitZero(this.safeString2(order, "newSize", "cumExecValue")));
        bool isMarketOrder = (type == "market");
        bool isBuy = (side == "buy");
        string? totalAmount = null;
        string? filledAmount = null;
        string? cost = null;
        string? remaining = null;
        string? totalFilled = this.safeString2(order, "accBaseVolume", "cumExecQty");
        if (isSpot)
        {
            if (isMargin)
            {
                totalAmount = this.safeString2(order, "baseSize", "qty");
                totalFilled = this.safeString2(order, "baseVolume", "cumExecQty");
                cost = this.safeString2(order, "fillTotalAmount", "cumExecValue");
            } else
            {
                string? partialFillAmount = this.safeString(order, "baseVolume");
                if ((partialFillAmount != null))
                {
                    filledAmount = partialFillAmount;
                } else
                {
                    filledAmount = totalFilled;
                }
                if (isMarketOrder)
                {
                    if (isBuy)
                    {
                        totalAmount = accBaseVolume;
                        cost = newSizeValue;
                    } else
                    {
                        totalAmount = newSizeValue;
                    }
                } else
                {
                    totalAmount = this.safeString2(order, "newSize", "qty");
                }
            }
        } else
        {
            // baseVolume should not be used for "amount" for contracts !
            filledAmount = this.safeString2(order, "baseVolume", "cumExecQty");
            totalAmount = this.safeString2(order, "size", "qty");
            cost = this.safeString2(order, "fillNotionalUsd", "cumExecValue");
        }
        remaining = Precise.stringSub(totalAmount, totalFilled);
        return this.safeOrder(new Dictionary<string, object>() {
            { "info", order },
            { "symbol", symbol },
            { "id", this.safeString(order, "orderId") },
            { "clientOrderId", this.safeString(order, "clientOid") },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "lastTradeTimestamp", this.safeInteger2(order, "uTime", "updatedTime") },
            { "type", type },
            { "timeInForce", this.safeStringUpper2(order, "force", "timeInForce") },
            { "postOnly", null },
            { "side", side },
            { "price", price },
            { "triggerPrice", triggerPrice },
            { "amount", totalAmount },
            { "cost", cost },
            { "average", avgPrice },
            { "filled", filledAmount },
            { "remaining", remaining },
            { "status", this.parseWsOrderStatus(rawStatus) },
            { "fee", feeObject },
            { "trades", null },
        }, market);
    }

    public virtual string? parseWsOrderStatus(string? status)
    {
        Dictionary<string, object> statuses = new Dictionary<string, object>() {
            { "new", "open" },
            { "live", "open" },
            { "partially_filled", "open" },
            { "filled", "closed" },
            { "cancelled", "canceled" },
            { "not_trigger", "open" },
        };
        return this.safeString(statuses, status, status);
    }

    /**
     * @method
     * @name bitget#watchMyTrades
     * @description watches trades made by the user
     * @see https://www.bitget.com/api-doc/contract/websocket/private/Fill-Channel
     * @see https://www.bitget.com/api-doc/uta/websocket/private/Fill-Channel
     * @param {str} symbol unified market symbol
     * @param {int} [since] the earliest time in ms to fetch trades for
     * @param {int} [limit] the maximum number of trades structures to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {boolean} [params.uta] set to true for the unified trading account (uta), defaults to false
     * @returns {object[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=trade-structure}
     */
    public async override Task<List<ccxt.Trade>> WatchMyTrades(string symbol = null, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        string symbolVar = symbol;
        Int64? limitVar = limit;
        parameters ??= new Dictionary<string, object>();
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        IDictionary<string, object> market = null;
        string messageHash = "myTrades";
        if ((symbolVar != null))
        {
            market = this.market(symbolVar);
            symbolVar = ((string)(market.ContainsKey("symbol") ? market["symbol"] : null));
            messageHash = ((messageHash + ":") + (symbolVar));
        }
        string? type = null;
        IList<object> typeparametersVariable = (IList<object>)this.handleMarketTypeAndParams("watchMyTrades", market, parameters);
        type = (string)typeparametersVariable[0];
        parameters = typeparametersVariable[1];
        string? instType = null;
        bool? uta = null;
        IList<object> utaparametersVariable = (IList<object>)this.handleOptionBoolAndParams(parameters, "watchMyTrades", "uta", false);
        uta = (bool?)utaparametersVariable[0];
        parameters = utaparametersVariable[1];
        if ((market == null) && type == "spot")
        {
            instType = "SPOT";
        } else
        {
            var instTypeparametersVariable = this.getInstType("watchMyTrades", market, uta, parameters);
            instType = (string)instTypeparametersVariable[0];
            parameters = instTypeparametersVariable[1];
        }
        if ((uta == true))
        {
            instType = "UTA";
        }
        string subscriptionHash = ("fill:" + instType);
        Dictionary<string, object> args = new Dictionary<string, object>() {
            { "instType", instType },
        };
        string topicOrChannel = "channel";
        if ((uta == true))
        {
            topicOrChannel = "topic";
        }
        args[(string)topicOrChannel] = "fill";
        if (uta != true)
        {
            args["instId"] = "default";
        } else
        {
            parameters = this.extend(parameters, new Dictionary<string, object>() {
                { "uta", true },
            });
        }
        object trades = await this.watchPrivate(uta, messageHash, subscriptionHash, args, parameters);
        if (this.newUpdates)
        {
            limitVar = ((Int64?)callDynamically(trades, "getLimit", new object[] {symbolVar, limitVar}));
        }
        return ccxt.BaseExchange.ToTradeList(this.filterBySymbolSinceLimit(trades, symbolVar, since, limitVar, true));
    }

    public virtual void handleMyTrades(WebSocketClient client, Dictionary<string, object> message)
    {
        //
        // spot
        // {
        //     "action": "snapshot",
        //     "arg": {
        //        "instType": "SPOT",
        //        "channel": "fill",
        //        "instId": "default"
