     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {str} [params.type] spot or contract if not provided this.options['defaultType'] is used
     * @param {string} [params.instType] one of 'SPOT', 'MARGIN', 'USDT-FUTURES', 'USDC-FUTURES', 'COIN-FUTURES', 'SUSDT-FUTURES', 'SUSDC-FUTURES' or 'SCOIN-FUTURES'
     * @param {string} [params.marginMode] 'isolated' or 'cross' for watching spot margin balances
     * @param {boolean} [params.uta] set to true for the unified trading account (uta), defaults to false
     * @returns {object} a [balance structure]{@link https://docs.ccxt.com/?id=balance-structure}
     */
    public async override Task<ccxt.Balances> WatchBalance(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        bool? uta = null;
        IList<object> utaparametersVariable = (IList<object>)this.handleOptionBoolAndParams(parameters, "watchBalance", "uta", false);
        uta = (bool?)utaparametersVariable[0];
        parameters = utaparametersVariable[1];
        string? type = null;
        IList<object> typeparametersVariable = (IList<object>)this.handleMarketTypeAndParams("watchBalance", null, parameters);
        type = (string)typeparametersVariable[0];
        parameters = typeparametersVariable[1];
        string? marginMode = null;
        IList<object> marginModeparametersVariable = (IList<object>)this.handleMarginModeAndParams("watchBalance", parameters);
        marginMode = (string)marginModeparametersVariable[0];
        parameters = marginModeparametersVariable[1];
        string? instType = null;
        string channel = "account";
        if ((type == "swap") || (type == "future"))
        {
            instType = "USDT-FUTURES";
        } else if ((marginMode != null))
        {
            instType = "MARGIN";
            if (uta != true)
            {
                if (marginMode == "isolated")
                {
                    channel = "account-isolated";
                } else
                {
                    channel = "account-crossed";
                }
            }
        } else if (uta != true)
        {
            instType = "SPOT";
        }
        IList<object> instTypeparametersVariable = (IList<object>)this.handleOptionStringAndParams(parameters, "watchBalance", "instType", instType);
        instType = (string)instTypeparametersVariable[0];
        parameters = instTypeparametersVariable[1];
        if ((uta == true))
        {
            instType = "UTA";
        }
        Dictionary<string, object> args = new Dictionary<string, object>() {
            { "instType", instType },
        };
        string topicOrChannel = "channel";
        if ((uta == true))
        {
            topicOrChannel = "topic";
        }
        args[(string)topicOrChannel] = channel;
        if (uta != true)
        {
            args["coin"] = "default";
        } else
        {
            parameters = this.extend(parameters, new Dictionary<string, object>() {
                { "uta", true },
            });
        }
        string instTypeLower = ((instType == null)) ? "" : instType.ToLower();
        string messageHash = ("balance:" + instTypeLower);
        return ccxt.BaseExchange.ToBalances(await this.watchPrivate(uta, messageHash, messageHash, args, parameters));
    }

    public virtual void handleBalance(WebSocketClient client, Dictionary<string, object> message)
    {
        //
        // spot
        //
        //     {
        //         "action": "snapshot",
        //         "arg": { "instType": "SPOT", "channel": "account", "coin": "default" },
        //         "data": [
        //             {
        //                 "coin": "USDT",
        //                 "available": "19.1430952856087",
        //                 "frozen": "7",
        //                 "locked": "0",
        //                 "limitAvailable": "0",
        //                 "uTime": "1701931970487"
        //             },
        //         ],
        //         "ts": 1701931970487
        //     }
        //
        // swap
        //
        //     {
        //         "action": "snapshot",
        //         "arg": { "instType": "USDT-FUTURES", "channel": "account", "coin": "default" },
        //         "data": [
        //             {
        //                 "marginCoin": "USDT",
        //                 "frozen": "5.36581500",
        //                 "available": "26.14309528",
        //                 "maxOpenPosAvailable": "20.77728028",
        //                 "maxTransferOut": "20.77728028",
        //                 "equity": "26.14309528",
        //                 "usdtEquity": "26.143095285166"
        //             }
        //         ],
        //         "ts": 1701932570822
        //     }
        //
        // margin
        //
        //     {
        //         "action": "snapshot",
        //         "arg": { "instType": "MARGIN", "channel": "account-crossed", "coin": "default" },
        //         "data": [
        //             {
        //                 "uTime": "1701933110544",
        //                 "id": "1096916799926710272",
        //                 "coin": "USDT",
        //                 "available": "16.24309528",
        //                 "borrow": "0.00000000",
        //                 "frozen": "9.90000000",
        //                 "interest": "0.00000000",
        //                 "coupon": "0.00000000"
        //             }
        //         ],
        //         "ts": 1701933110544
        //     }
        //
        // uta
        //
        //     {
        //         "data": [{
        //             "unrealisedPnL": "-10116.55",
        //             "totalEquity": "4976919.05",
        //             "positionMgnRatio": "0",
        //             "mmr": "408.08",
        //             "effEquity": "4847952.35",
        //             "imr": "17795.97",
        //             "mgnRatio": "0",
        //             "coin": [{
        //                 "debts": "0",
        //                 "balance": "0.9992",
        //                 "available": "0.9992",
        //                 "borrow": "0",
        //                 "locked": "0",
        //                 "equity": "0.9992",
        //                 "coin": "ETH",
        //                 "usdValue": "2488.667472"
        //             }]
        //         }],
        //         "arg": {
        //             "instType": "UTA",
        //             "topic": "account"
        //         },
        //         "action": "snapshot",
        //         "ts": 1740546523244
        //     }
        //
        IDictionary<string, object> arg = this.safeDict(message, "arg", new Dictionary<string, object>() {});
        string? instType = this.safeStringLower(arg, "instType");
        List<object> data = this.safeList(message, "data", new List<object>() {});
        for (int i = 0; i < data.Count; i++)
        {
            object rawBalance = data[i];
            if (instType == "uta")
            {
                List<object> coins = this.safeList(rawBalance, "coin", new List<object>() {});
                for (int j = 0; j < coins.Count; j++)
                {
                    IDictionary<string, object> entry = this.safeDict(coins, j);
                    string? currencyId = this.safeString(entry, "coin");
                    string? code = this.safeCurrencyCode(currencyId);
                    object account = this.account();
                    if (((code != null)) && (inOp(this.balance, code)))
                    {
                        account = getValue(this.balance, code);
                    }
                    string? borrow = this.safeString(entry, "borrow");
                    string? debts = this.safeString(entry, "debts");
                    if (((borrow != null)) || ((debts != null)))
                    {
                        ((IDictionary<string,object>)account)["debt"] = Precise.stringAdd(borrow, debts);
                    }
                    ((IDictionary<string,object>)account)["free"] = this.safeString(entry, "available");
                    ((IDictionary<string,object>)account)["used"] = this.safeString(entry, "locked");
                    ((IDictionary<string,object>)account)["total"] = this.safeString(entry, "balance");
                    if ((code != null))
                    {
                        ((IDictionary<string,object>)this.balance)[(string)code] = account;
                    }
                }
            } else
            {
                string? currencyId = this.safeString2(rawBalance, "coin", "marginCoin");
                string? code = this.safeCurrencyCode(currencyId);
                object account = this.account();
                if (((code != null)) && (inOp(this.balance, code)))
                {
                    account = getValue(this.balance, code);
                }
                string? borrow = this.safeString(rawBalance, "borrow");
                if ((borrow != null))
                {
                    string? interest = this.safeString(rawBalance, "interest");
                    ((IDictionary<string,object>)account)["debt"] = Precise.stringAdd(borrow, interest);
                }
                string freeQuery = "available";
                if (inOp(rawBalance, "maxTransferOut"))
                {
                    freeQuery = "maxTransferOut";
                }
                ((IDictionary<string,object>)account)["free"] = this.safeString(rawBalance, freeQuery);
                ((IDictionary<string,object>)account)["total"] = this.safeString(rawBalance, "equity");
                ((IDictionary<string,object>)account)["used"] = this.safeString(rawBalance, "frozen");
                if ((code != null))
                {
                    ((IDictionary<string,object>)this.balance)[(string)code] = account;
                }
            }
        }
        // REST parseBalance sets info, keep the ws structure at parity,
        // see https://github.com/ccxt/ccxt/issues/21973
        ((IDictionary<string,object>)this.balance)["info"] = message;
        this.balance = this.safeBalance(this.balance);
        string messageHash = ("balance:" + instType);
        client.resolve(this.balance, messageHash);
    }

