        if (inOp(this.orderbooks, symbol))
        {
            ((IDictionary<string,object>)this.orderbooks).Remove(symbol);
        }
        if (inOp(client.subscriptions, subMessageHash))
        {
            ((IDictionary<string,object>)client.subscriptions).Remove(subMessageHash);
